// ============================================================================
//  "Extract product URLs" Code node — parse the product sitemap and output one
//  item per product URL. Products are the /ar/<shortcode> pages.
//  Input = the sitemap XML (from "Get sitemap", json.data).
// ============================================================================
const items = $input.all();
const xml = String(items[0].json.data ?? items[0].json.body ?? '');

const urls = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)]
	.map((m) => m[1].trim())
	// product short-code pages look like https://legendsleepsa.com/ar/jZxrezB
	.filter((u) => /\/ar\/[A-Za-z0-9]{5,}\/?$/.test(u));

return urls.map((u) => ({ json: { url: u } }));

// ============================================================================
//  "Parse & Validate" Code node — extract price/discount from each product page
//  and flag products whose price doesn't match the shown discount %.
//  Input  = items from "Fetch products" (each json.data = product page HTML,
//           json.url = the product URL).
//  Output = one item per MISMATCH, with the numbers + a small thumbnail URL.
// ============================================================================

// Flag a product if its price is off from the shown-% price by at least this.
const TOLERANCE_SAR = 1;

function num(s) {
	return s == null ? null : parseFloat(String(s).replace(/,/g, ''));
}

// The "Fetch products" HTTP node replaces json with the response body, so the
// product URL is taken from the "Extract product URLs" node, aligned by index.
let urlList = [];
try {
	urlList = $('Extract product URLs').all().map((x) => x.json.url);
} catch (e) {
	urlList = [];
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
	const it = items[i];
	const html = String(it.json.data ?? it.json.body ?? it.json.html ?? '');
	const url = String(it.json.url ?? urlList[i] ?? '');

	// original (crossed-out) price
	let m = html.match(/before-price[^>]*line-through"[^>]*>\s*([0-9,]+\.?[0-9]*)/i);
	const original = m ? num(m[1]) : null;

	// current (sale) price
	m = html.match(/sale_price:amount"\s+content="([0-9.]+)"/i);
	const current = m ? num(m[1]) : null;

	// shown discount %  (Arabic "خصم NN%")
	m = html.match(/خصم[\s ]*([0-9]+)\s*%/);
	const shownPct = m ? parseInt(m[1], 10) : null;

	// product name (JSON-LD)
	m = html.match(/"@type":"Product","name":"([^"]+)"/);
	const name = m ? m[1] : '';

	// product image (first Salla CDN image in the product JSON-LD)
	m = html.match(/"image":"(https:\\?\/\\?\/cdn\.salla\.sa[^"]+?\.(?:png|jpe?g|webp))/i);
	const image = m ? m[1].replace(/\\\//g, '/') : null;

	// short code from the URL (…/ar/CODE)
	m = url.match(/\/ar\/([A-Za-z0-9]+)\/?$/);
	const code = m ? m[1] : '';

	// only products that are actually on sale can be audited
	if (!(original && current && shownPct)) continue;

	const expected = Math.round(original * (1 - shownPct / 100) * 100) / 100;
	const actualPct = Math.round((1 - current / original) * 1000) / 10;
	const diff = Math.round((current - expected) * 100) / 100;

	if (Math.abs(diff) >= TOLERANCE_SAR) {
		out.push({
			json: {
				code,
				url,
				name,
				original,
				current,
				shownPct,
				expected, // what the price SHOULD be for the shown %
				actualPct, // the real discount % the price gives
				diff, // current - expected  (＋ = charged too much vs shown %)
				image,
				thumbUrl: image
					? `https://cdn.salla.sa/cdn-cgi/image/width=120,quality=70/${image}`
					: null,
			},
		});
	}
}

return out;

// ============================================================================
//  "Build PDF" Code node — render the mismatch report as a PDF with thumbnails.
//  Fields come from "Parse & Validate"; the thumbnails come from this node's
//  input (the "Fetch thumbnails" HTTP node, binary `data`), aligned by index.
//  Requires `pdf-lib`. Uses only Latin/number text (pdf-lib can't shape Arabic),
//  so products are identified by their code + image + link.
// ============================================================================
const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');
const helpers = this.helpers;

const rows = $('Parse & Validate').all().map((i) => i.json);
const thumbCount = $input.all().length;

const doc = await PDFDocument.create();
const font = await doc.embedFont(StandardFonts.Helvetica);
const bold = await doc.embedFont(StandardFonts.HelveticaBold);

const W = 595, H = 842, M = 40, ROW = 78;
let page, y;
function newPage() {
	page = doc.addPage();
	page.setSize(W, H);
	y = H - M;
}
function text(s, x, yy, size, f, color) {
	page.drawText(String(s), { x, y: yy, size, font: f || font, color: color || rgb(0, 0, 0) });
}
newPage();

// header
text('Legend Sleep - Discount Audit', M, y, 18, bold, rgb(0.12, 0.12, 0.42));
y -= 22;
text(`Products with a price / discount-% mismatch: ${rows.length}`, M, y, 11, font);
y -= 10;
page.drawRectangle({ x: M, y, width: W - 2 * M, height: 1, color: rgb(0.6, 0.6, 0.6) });
y -= 18;

for (let i = 0; i < rows.length; i++) {
	const r = rows[i];
	if (y < M + ROW) newPage();

	// thumbnail (aligned by index; skip if fetch failed or format unknown)
	if (i < thumbCount) {
		try {
			const buf = await helpers.getBinaryDataBuffer(i, 'data');
			if (buf && buf.length > 100) {
				const isJpg = buf[0] === 0xff && buf[1] === 0xd8;
				const img = isJpg ? await doc.embedJpg(buf) : await doc.embedPng(buf);
				page.drawImage(img, { x: M, y: y - 58, width: 58, height: 58 });
			}
		} catch (e) {
			/* no image for this row */
		}
	}

	const tx = M + 72;
	const sign = r.diff > 0 ? '+' : '';
	text(r.code, tx, y - 8, 12, bold);
	text(`Original ${r.original}   Current ${r.current}   Shown ${r.shownPct}%`, tx, y - 24, 10, font);
	text(
		`Should be ${r.expected}   Real ${r.actualPct}%   Off by ${sign}${r.diff} SAR`,
		tx,
		y - 39,
		10,
		bold,
		rgb(0.8, 0, 0),
	);
	text(r.url, tx, y - 54, 8, font, rgb(0.3, 0.3, 0.7));

	y -= ROW;
	page.drawRectangle({ x: M, y: y + 8, width: W - 2 * M, height: 0.5, color: rgb(0.85, 0.85, 0.85) });
}

const fileName = 'discount-audit.pdf';
const bytes = await doc.save();
const bin = await helpers.prepareBinaryData(Buffer.from(bytes), fileName, 'application/pdf');

let recipient = '';
try {
	recipient = $('On form submission').first().json['Send To Email'];
} catch (e) {
	/* scheduled run without a form */
}

return [{ json: { mismatches: rows.length, fileName, recipient }, binary: { data: bin } }];
